from review import card,save,DATE
def b(t,s,r=None):
 d=dict(title=t,text=s)
 if r:d['citation']=r
 return d
def sm(s,r):return dict(sentences=s,basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=r)
def imp(c,s):return dict(score=c['importance']['score'],method='editorial',reason=s+' Existing numerical score retained.',assessed_on=DATE)

i='TCS-2093';_,c=card(i);refs=c['references'];refs[0]['locator']='ITCS 2024, article 10: Definition 1.5, Section 2 definition of NDepth, Theorem 4.3, Section 4.2.2 and conclusion read. The class uses input-aware polylog-time uniform NAND formulas; N does not mean nondeterminism.'
refs.append(dict(id='full',title='Towards Stronger Depth Lower Bounds — full version',authors='Gabriel Bathie, R. Ryan Williams',year=2023,url='https://eccc.weizmann.ac.il/report/2023/184/',locator='Full PDF: Definition 1.5 and the conditional depth hierarchy theorem with its following open-question paragraph checked. The descriptor receives x and can dynamically select a subformula, while the displayed notation still indexes the formula only by n.'))
issue='Definition 1.5 gives the gate descriptor random access to x and explicitly permits dynamic subformula selection, but writes a single fixed formula φ_n for each n. To turn this into an unambiguous benchmark, specify whether the descriptor may change the represented formula with x, and precisely what correctness must hold for the resulting input-dependent description. Removing x would silently replace the source’s stronger uniformity notion. The open paragraph also says “any a<b”, whereas the accompanying theorem is stated for 1<a<b; the intended coefficient range should be fixed explicitly.'
save(i,dict(title='An unconditional hierarchy for uniform NAND depth',formal='Can the source’s input-aware polylog-time uniform NAND-depth classes be separated unconditionally: NDepth[a log₂n] ⊊ NDepth[b log₂n] for every pair of admissible constants a<b? The immediate comparison is the paper’s conditional theorem for 1<a<b. The input-aware gate-description convention and the intended coefficient range need clarification before this becomes a fully specified benchmark.',definitions='A NAND gate takes two bits u,v and outputs ¬(u∧v). A NAND formula is a rooted binary tree of such gates whose leaves are input bits, their negations or Boolean constants; depth is the largest number of gates on an input-to-output path. For c≥0, the source writes NDepth[c log₂n] for languages decided by uniform NAND formulas with depth at most (c+o(1))log₂n; the o(1) tends to zero as input length n grows. The coefficient c is therefore meaningful and is not hidden in O(log n). In Definition 1.5 a single random-access machine A receives n, an n-bit input x, and a binary address b describing a path from the root (0 for left, 1 for right). It must describe the gate at that address in time (log n)^O(1). The source calls this input-aware uniformity and says it can select subformulas using bits of x. Its displayed definition still denotes the formula by φ_n rather than φ_{n,x}; that distinction is left explicit here. Strict class containment means that some language belongs to the larger-depth class and to no formula family in the smaller-depth class. It is a separation of deterministic NAND computations, not a comparison of nondeterministic time bounds.',question_type='yes_no',answer_criterion='After fixing the source’s input-aware representation and coefficient range, prove strict containment for every required a<b without assuming that SAT or NTIME[n] has shallow NAND formulas, or refute that hierarchy in the same model. A lower bound for SAT alone, a conditional hierarchy, or a separation under a different uniformity notion does not settle it.',context_blocks=[b('A constant factor in depth is the resource being measured','Both classes have logarithmic depth, but b log₂n permits more sequential gate layers than a log₂n. The question asks whether that extra constant factor always buys computational power.'),b('The paper’s hierarchy is conditional','Theorem 4.3 proves strict containment for all 1<a<b under the assumption that NTIME[n]⊆NDepth[c log₂n] for some c>0. The open question removes this assumption.', 'primary'),b('The SAT result is a different statement','The paper rules out uniform NAND formulas for SAT below the coefficient 4 cos(π/7), approximately 3.603. It does not put a separating language into each proposed upper-depth class, as a full hierarchy theorem would require.', 'primary'),b('The gate basis and uniformity cannot be discarded','Using arbitrary two-input Boolean gates, treating negations differently at internal gates, or replacing the input-aware descriptor by an input-independent one changes the fine depth measure. These choices matter when the leading logarithmic coefficient is the target.')],why='Would give a fine-grained hierarchy for parallel Boolean computation in a uniform bounded-fan-in model, beyond a lower bound for one chosen problem.',progress=[dict(date='2024',text='Bathie and Williams prove a conditional hierarchy and an unconditional SAT lower bound, and ask for an unconditional hierarchy.',citation='primary')],references=refs,status='uncertain',status_note='The conference and full-version definitions and theorems were checked, and no later unconditional hierarchy was located through 12 September 2026. The source’s input-aware formula convention needs clarification before the exact class separation can be certified as self-contained.',model_self_contained=False,requires_context=True,statement_review=dict(reviewed_on=DATE,status='needs_specification',notes=['Recovered the NAND basis, leading depth constants and conditional comparison theorem.'],remaining_issue=issue),importance=imp(c,'A general hierarchy question for the constant factors in uniform logarithmic Boolean depth.'),review_note='Restored the truncated a<b comparison and distinguished NAND depth from nondeterminism. Preserved the source’s nonstandard input-aware uniformity instead of silently substituting a conventional circuit class.',working_summary=sm(['The question asks whether every larger constant multiplying log n in NAND depth gives a strictly stronger uniform computation class.','The source proves this only under a shallow-formula assumption for nondeterministic linear-time computations.','Its separate lower bound for SAT does not establish the whole hierarchy.','The uniformity machine can inspect the input while describing gates.','That input dependence and the coefficient range need precise conventions before the recovered question is a complete benchmark.'],['primary','full'])),state='improved_unfinished',notes=['Recovered the truncated hierarchy comparison and the precise NAND-depth scale.','Defined the gate basis, root-path descriptor and strict language separation.','Recorded the input-aware representation ambiguity rather than substituting ordinary uniformity.'],checked_sources=[r['url'] for r in refs])

i='TCS-2097';_,c=card(i);refs=c['references'];refs[0]['locator']='OPODIS 2024, article 16: Section 2 and Definition 1, large-message overhead definition, Section 6/Theorem 20 and Section 8 conjecture read. The proved bound assumes three rounds and o(|m|n) first-round sender communication.'
refs.extend([
dict(id='minicast',title='MiniCast: Minimizing the Communication Complexity of Reliable Broadcast',authors='Thomas Locher, Victor Shoup',year=2025,url='https://eprint.iacr.org/2024/571',locator='Eurocrypt 2025; full ePrint introduction, communication model and conclusion read. Achieves 1.5|m|n+O(κn²log n) communication in four good-case rounds and retains the general lower bound as a conjecture.'),
dict(id='rounds',title='Towards Reliable Broadcast with Optimal Communication and Round Complexity',authors='Thomas Locher, Victor Shoup',year=2025,url='https://eprint.iacr.org/2025/779',locator='Full version dated 3 October 2025: abstract and Sections 1–2 read. Gives a three-round bound with the same leading communication coefficient and a two-round signature-based unbalanced variant. Optimality remains tied to the restricted lower bound.'),
dict(id='failure',title='Efficient Byzantine Reliable Broadcast in the Failure Case',authors='Thomas Locher',year=2025,url='https://doi.org/10.4230/LIPIcs.OPODIS.2025.12',locator='OPODIS 2025: abstract, introduction, related work and conclusion read. Still describes the general 3/2 overhead as conjecturally optimal; its 5/3 lower bound imposes an initial full-message broadcast condition.')])
save(i,dict(title='A general 3/2 communication lower bound for reliable broadcast',formal='Must every Byzantine reliable-broadcast protocol in the source’s asynchronous authenticated point-to-point model have worst-case large-message communication overhead at least 3/2 asymptotically, when n=3t+1 and up to t parties can be Byzantine, even without a three-round delivery bound or a sublinear-in-n first-round sender load? This selects the source’s version with both restrictions removed.',definitions='There are n=3t+1 parties with pairwise authenticated channels and a designated sender holding a message m of ℓ bits. Honest-to-honest messages are eventually delivered, with no upper bound on delay; Byzantine parties may deviate arbitrarily. Validity requires every honest party eventually to deliver m when the sender is honest. Agreement requires all honest deliveries to have the same value. Integrity allows each honest party at most one delivery, and totality requires that if one honest party delivers, all honest parties eventually do so. A Byzantine sender may cause no delivery. Let C_A(n,ℓ) be the worst-case total number of bits sent by honest parties in one execution of protocol A, over admissible inputs, faults and delivery schedules. Faulty-party transmissions are not charged. For a faulty sender, the source measures the effective message length by the largest payload fragment an honest party sends under the protocol’s declared encoding. The large-message overhead is L_A(n)=lim_{ℓ→∞} C_A(n,ℓ)/(nℓ), when the limit exists. The proposed bound is liminf_{t→∞}L_A(3t+1)≥3/2; equivalently, no constant improvement below 3/2 is possible uniformly for all sufficiently large n and sufficiently long messages. The source permits collision-resistant hashing and, for signature-based protocols, signature setup, counting their transmitted bits through a security parameter κ. The payload comparison discards lower-order terms in ℓ, such as O(κn²log n), and uses the source’s cryptographic correctness convention. There is no bound of three on the number of rounds and no restriction that the sender’s first-round total be o(nℓ).',question_type='yes_no',answer_criterion='Prove the universal 3/2 lower bound in the stated unrestricted asynchronous model, or give a correct protocol with a strictly smaller asymptotic worst-case payload coefficient. An upper bound of 3/2 or a lower bound only for three-round, weakly balanced protocols does not resolve this question.',context_blocks=[b('The coefficient matters after linear scaling is known','Sending an ℓ-bit payload to n parties naturally costs on the order of nℓ bits. The open question concerns the leading constant caused by fault tolerance, rather than whether communication can be linear in payload length.'),b('Two restrictions remain in the known lower bound','The original theorem applies even to synchronous crash faults, but requires delivery within three rounds and only o(nℓ) first-round bits from the sender. It does not establish the lower bound for protocols that use more rounds or concentrate the load on the sender.', 'primary'),b('Matching upper bounds now exist','MiniCast attains leading coefficient 3/2 in the worst case. The later Locher–Shoup work reduces its good-case latency to three rounds and also gives signature-based two-round variants. These constructions strengthen the evidence for optimality but do not prove the general lower bound.', 'rounds'),b('Failure-free behavior is not the objective','A protocol may use approximately nℓ bits when everything goes well and still need 1.5nℓ bits in its worst execution. The conjecture is about the latter, counting all communication sent by honest parties even when a faulty sender prevents delivery.', 'minicast')],why='Would settle the leading bandwidth cost of reliable broadcast, a primitive used inside many fault-tolerant distributed protocols.',progress=[dict(date='2024',text='Locher proves a 3/2 lower bound for three-round protocols with restricted first-round sender load and asks to remove these restrictions.',citation='primary'),dict(date='2025',text='MiniCast provides a general worst-case 3/2 upper bound; subsequent protocols improve latency while retaining that coefficient.',citation='minicast'),dict(date='2025-10-03',text='The revised Locher–Shoup follow-up still invokes optimality only under the restricted lower-bound conditions.',citation='rounds')],references=refs,status='source_open',status_note='Original restrictions and overhead definition checked against MiniCast, the October 2025 full follow-up and the OPODIS 2025 failure-case paper. No general lower-bound resolution was located through 12 September 2026. The question here concerns the unrestricted asynchronous version, not an unrestricted synchronous crash-fault claim.',model_self_contained=True,requires_context=False,importance=imp(c,'Would determine the optimal leading communication constant for Byzantine reliable broadcast.'),review_note='Recovered both omitted restrictions and the payload-normalized worst-case objective. Added the later 3/2 upper bounds without treating them as a lower-bound resolution; retained the source’s cryptographic communication convention.',working_summary=sm(['Reliable broadcast must give all honest parties a consistent outcome despite Byzantine behavior.','New protocols can do this with leading worst-case communication cost 1.5 times n times the payload length.','The open question asks whether that constant is unavoidable for all protocols.','The proved lower bound still restricts latency and first-round sender communication.','Removing both restrictions is different from improving a protocol’s failure-free cost.'],['primary','minicast','rounds','failure'])),notes=['Restored the 3/2 target, asymptotic overhead and both restrictions to be removed.','Defined reliable broadcast and honest-party worst-case bit counting.','Added MiniCast and later latency improvements while preserving the open general lower bound.'],checked_sources=[r['url'] for r in refs]+['https://arxiv.org/abs/2404.08070','https://www.shoup.net/papers/'])
